export default JSON.parse('{"1060":{"mistakes":["Прогин у попереку у верхній точці","Упор на носки","Неповне розгинання в тазостегновому суглобі"],"tips":["Притисни підборіддя й опусти ребра, щоб рух завершували сідниці, а не поперек.","Постав стопи так, щоб у верхній точці гомілки були вертикальні."]},"1162":{"mistakes":["Сильний прогин назад","Штанга йде вперед, оминаючи обличчя","Розслаблені прес і сідниці"],"tips":["Напруж сідниці й прес, щоб поперек залишався рівним.","Відведи голову назад, коли штанга проходить повз обличчя, а вгорі поверни її під штангу."]},"2224":{"mistakes":["Повне розгинання колін","Відривання поперека від спинки","Ступні занадто близько до нижнього краю платформи"],"tips":["Протягом усієї вправи притискай спину, зокрема поперек, до спинки. Це захистить хребет і забезпечить правильну роботу ніг.","Опускай платформу лише доти, доки поперек залишається притиснутим."]},"2267":{"mistakes":["Повне розгинання колін","Таз відривається від сидіння в нижній точці","Коліна заходять всередину"],"tips":["Тримай коліна в одній лінії з носками протягом усього руху.","Тисни всією стопою, а не лише носками."]},"0025":{"mistakes":["Відбивання штанги від грудей","Лікті розведені строго в сторони","Відривання таза від лави"],"tips":["Перед тим як зняти штангу, зведи й опусти лопатки та тримай їх так увесь підхід.","Опускай штангу до нижньої частини грудей, лікті під кутом приблизно 45 до 70 градусів до тулуба."]},"0027":{"mistakes":["Округлення спини","Корпус піднімається з кожним повторенням","Ривки вагою за рахунок таза"],"tips":["Тягни штангу до нижніх ребер і зводь лопатки у верхній точці.","Тримай нахил корпусу незмінним. Якщо не виходить, зменш вагу."]},"0032":{"mistakes":["Округлення спини","Штанга віддаляється від ніг","Таз піднімається раніше, ніж штанга відривається від підлоги","Відхилення назад у верхній точці"],"tips":["Веди штангу так близько, щоб вона ковзала по гомілках і стегнах на всьому шляху.","Перед тягою вибери люфт штанги й напруж корпус."]},"0043":{"mistakes":["Коліна заходять всередину","Відривання п\'ят від підлоги","Округлення поперека в нижній точці"],"tips":["Перед кожним повторенням глибоко вдихни й напруж корпус.","Розводь коліна в напрямку носків і тримай вагу над серединою стопи."]},"0085":{"mistakes":["Округлення спини","Надмірне згинання колін, і вправа перетворюється на присід","Штанга відходить від ніг"],"tips":["Відводь таз назад, ніби зачиняєш ним двері позаду.","Опускайся лише до відчуття сильного розтягнення задньої поверхні стегна."]},"0198":{"mistakes":["Сильне відхилення назад","Тяга за голову","Різке повернення руків\'я вгору"],"tips":["Тягни руків\'я до верхньої частини грудей, ведучи рух ліктями.","Повертай руків\'я вгору під контролем до повного випрямлення рук."]},"0201":{"mistakes":["Лікті розходяться або виходять уперед","Нахил над руків\'ям, щоб тиснути вагою тіла","Неповне розгинання рук"],"tips":["Тримай плечі нерухомо біля тулуба. Рухаються лише передпліччя.","Затримайся з прямими руками й напруж трицепс."]},"0251":{"mistakes":["Плечі піднімаються до вух","Надто глибоке опускання","Розгойдування ніг"],"tips":["Злегка нахили корпус уперед, щоб більше навантажити груди.","Опускайся, доки плечі не стануть приблизно паралельно підлозі."]},"0289":{"mistakes":["Гантелі розходяться в сторони в нижній точці","Лікті розведені строго в сторони","Ривок із нижньої точки"],"tips":["Тримай лопатки зведеними, а стопи впертими в підлогу.","Опускай гантелі до рівня грудей, потім вичавлюй угору, трохи зводячи їх."]},"0294":{"mistakes":["Розгойдування корпусу","Лікті виходять уперед","Різке опускання гантелей"],"tips":["Притискай лікті до боків.","Опускай гантелі повільніше, ніж піднімаєш."]},"0334":{"mistakes":["Закидання гантелей ривком","Піднімання рук вище плечей","Піднімання плечей до вух"],"tips":["Веди рух ліктями й тримай їх злегка зігнутими.","Бери невелику вагу й опускай її повільно."]},"0336":{"mistakes":["Переднє коліно заходить всередину","Крок такий короткий, що п\'ята передньої ноги відривається","Нахил корпусу вперед"],"tips":["Роби достатньо довгий крок, щоб обидва коліна згиналися приблизно до 90 градусів.","Повертайся у вихідне положення, відштовхуючись п\'ятою передньої ноги."]},"0463":{"mistakes":["Провисання таза","Таз піднятий надто високо","Затримка дихання"],"tips":["Напруж сідниці й підтягни живіт.","Завершуй підхід, коли техніка починає ламатися, а не лише за таймером."]},"0652":{"mistakes":["Розгойдування тіла","Неповне опускання в нижній точці","Підборіддя не доходить до перекладини"],"tips":["Починай кожне повторення з опускання лопаток, а потім згинай лікті.","Тримай ноги нерухомо, а корпус напруженим, щоб не розгойдуватися."]},"0662":{"mistakes":["Провисання таза","Лікті розведені строго в сторони","Неповна амплітуда, груди не опускаються до підлоги"],"tips":["Тримай тіло в одну лінію від голови до п\'ят, напружуючи сідниці й прес.","Якщо повні віджимання поки важкі, спирайся руками на лаву замість того, щоб скорочувати амплітуду."]},"0739":{"mistakes":["Повне розгинання колін","Відривання поперека від спинки","Ступні занадто близько до нижнього краю платформи"],"tips":["Протягом усієї вправи притискай спину, зокрема поперек, до спинки. Це захистить хребет і забезпечить правильну роботу ніг.","Опускай платформу лише доти, доки поперек залишається притиснутим."]},"0861":{"mistakes":["Розгойдування корпусу вперед і назад","Округлення спини, коли вага повертається","Піднімання плечей до вух"],"tips":["Сиди рівно й тримай корпус нерухомо. Працюють руки та спина.","Зводь лопатки, коли руків\'я доходить до живота."]}}')
